local function readFile(path)
    local file = assert(io.open(path, "rb"))
    local source = file:read("*a")
    file:close()
    return source
end

local main = readFile("main.lua")
local servers = readFile("ServersPage.lua")
local settings = readFile("ServerSettingsPage.lua")
local browser = readFile("ServerLibraryBrowser.lua")
local style = readFile("DeluxeUIStyle.lua")
local menu = readFile("PluginMenuController.lua")

local function contains(source, text, message)
    assert(source:find(text, 1, true), message or ("missing expected integration: " .. text))
end

local function excludes(source, text, message)
    assert(not source:find(text, 1, true), message or ("unexpected legacy integration: " .. text))
end

