local save_callback_start = assert(main:find('on_save = function(current, draft, password)', 1, true))
local signup_callback_start = assert(main:find('on_signup = function(current, draft, password)', save_callback_start, true))
local save_callback = main:sub(save_callback_start, signup_callback_start - 1)
assert(save_callback:find('self:testServer(saved, {', 1, true), "every Save must automatically authenticate and refresh server capabilities")
